/**
 * Roger Coqart "Square Series" - Animated Contrast Loop
 * 
 * This tribute to Roger Coqart's algorithmic art explores geometric density and growth.
 * The animation cycles through four distinct phases of black and white color inversions.
 * Each transition uses a specific fading technique to seamlessly bridge high-contrast states.
 * 
 * Inspired by Benjamin Fox's ReCode Project (2012)
 */
let style = document.createElement('style');
style.innerHTML = `body { margin: 0; padding: 0; overflow: hidden; }`;
document.head.appendChild(style);
let n = 7; // Grid size: 7x7 tiles per group
let tileSize = 30; // Size of each individual square tile in pixels
let margin = 40; // Empty space around the grid edges
let gridData = []; // Storage for tile patterns and positions
let animTimer = 0; // Frame counter for the current state
let state = 0; // State: 0 = Growing, 1 = Waiting, 2 = Fading
let loopStep = 0; // Phase: 0 (B-B), 1 (B-W), 2 (W-W), 3 (W-B)
const FPS = 60; // Desired frames per second

let duration = {
  grow: 120, // 2 seconds for lines to extend
  wait: 30,  // 0.5 seconds of stillness
  fade: 90   // 1.5 seconds for transitions
};

function setup() {
  createCanvas(windowWidth, windowHeight); // Initialize canvas to fill screen
  frameRate(FPS); // Set the animation speed
  initGrid(); // Generate the first random grid layout
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight); // Update canvas size on resize
  initGrid(); // Re-calculate grid for new dimensions
}

function initGrid() {
  gridData = []; // Reset the data array
  let groupSize = n * tileSize; // Total width of a 7x7 tile group
  let screenCols = Math.floor((width - margin) / groupSize); // Calculate horizontal fit
  let screenRows = Math.floor((height - margin) / groupSize); // Calculate vertical fit
  let totalW = screenCols * groupSize; // Final width of the grid assembly
  let totalH = screenRows * groupSize; // Final height of the grid assembly
  let offsetX = (width - totalW) / 2; // Horizontal centering math
  let offsetY = (height - totalH) / 2; // Vertical centering math
  let centerIdx = Math.floor(n / 2); // Identify the center of the 7x7 group

  for (let y = 0; y < screenRows; y++) { // Loop through rows of groups
    for (let x = 0; x < screenCols; x++) { // Loop through columns of groups
      let tiles = []; // Array to hold individual tiles in this group
      let isDense = (x + y) % 2 === 0; // Checkerboard density pattern
      let maxLines = isDense ? 8 : 4; // Dense tiles have more possible lines
      let reduceAmount = isDense ? 2 : 1; // Faster reduction for dense tiles

      for (let i = 0; i < n; i++) { // X-axis within the group
        for (let j = 0; j < n; j++) { // Y-axis within the group
          let dist = Math.max(Math.abs(i - centerIdx), Math.abs(j - centerIdx)); // Chebyshev distance
          let numLines = maxLines - (dist * reduceAmount); // Decrease lines further from center
          let lineTypes = [1, 2, 3, 4, 5, 6, 7, 8]; // All possible line patterns
          shuffle(lineTypes, true); // Randomize line order
          tiles.push({ // Define tile properties
            lines: lineTypes.slice(0, Math.max(0, numLines)), // Pick subset of lines
            delay: random(0, 60), // Staggered start time for growth
            posX: i * tileSize, // Local X coordinate
            posY: j * tileSize  // Local Y coordinate
          });
        }
      }
      gridData.push({ x: offsetX + x * groupSize, y: offsetY + y * groupSize, tiles: tiles }); // Add to grid
    }
  }
  animTimer = 0; // Reset animation timer for new layout
  state = 0; // Restart at the growing phase
}

function draw() {
  animTimer++; // Advance global frame counter

  let bgColor, strokeColor; // Variables to store calculated colors
  let opacity = 255; // Default line visibility
  let growthProgress = 1.0; // Default line length

  // Define base colors based on the current loop phase
  if (loopStep === 0 || loopStep === 1) {
    bgColor = 0; // Background is black for steps 0 and 1
    strokeColor = 255; // Lines are white for steps 0 and 1
  } else {
    bgColor = 255; // Background is white for steps 2 and 3
    strokeColor = 0; // Lines are black for steps 2 and 3
  }

  // Handle Animation State Machine
  if (state === 0) { // GROWING PHASE
    growthProgress = map(animTimer, 0, duration.grow, 0, 1.0, true); // Progress from 0 to 1
    if (animTimer >= duration.grow + 60) { // Wait for staggered lines to finish
      state = 1; // Move to stillness
      animTimer = 0; // Reset timer
    }
  } 
  else if (state === 1) { // WAITING PHASE
    growthProgress = 1.0; // Keep lines fully grown
    if (animTimer >= duration.wait) { // Stay still for 0.5s
      state = 2; // Move to transition
      animTimer = 0; // Reset timer
    }
  } 
  else if (state === 2) { // FADING/TRANSITION PHASE
    growthProgress = 1.0; // Lines remain at full length
    let fadeProgress = map(animTimer, 0, duration.fade, 0, 1.0, true); // Normalize fade time

    // Specific logic for each phase's transition
    if (loopStep === 0) {
      opacity = map(fadeProgress, 0, 1, 255, 0); // Fade lines to transparent (Black to Black)
    } 
    else if (loopStep === 1) {
      bgColor = map(fadeProgress, 0, 1, 0, 255); // Fade background to white (Black to White)
    } 
    else if (loopStep === 2) {
      strokeColor = map(fadeProgress, 0, 1, 0, 255); // Fade black lines to white (White to White)
    } 
    else if (loopStep === 3) {
      bgColor = map(fadeProgress, 0, 1, 255, 0); // Fade background to black (White to Black)
    }

    if (animTimer >= duration.fade) { // Check if transition is finished
      loopStep = (loopStep + 1) % 4; // Cycle to the next step
      initGrid(); // Generate new geometry for the next loop
    }
  }

  background(bgColor); // Fill background with calculated color
  strokeWeight(2); // Set consistent line thickness

  for (let g of gridData) { // Iterate through every tile group
    push(); // Save coordinate system
    translate(g.x, g.y); // Position group on screen
    for (let t of g.tiles) { // Iterate through tiles in group
      let tProgress = state > 0 ? 1.0 : constrain(map(animTimer, t.delay, duration.grow, 0, 1.0), 0, 1.0); // Local growth
      stroke(strokeColor, opacity); // Apply calculated stroke and opacity
      push(); // Save state for tile translation
      translate(t.posX, t.posY); // Move to tile position
      for (let type of t.lines) { // Draw each line pattern
        drawPerfectLineFromCenter(type, tProgress, tileSize); // Growth animation helper
      }
      pop(); // Restore state
    }
    pop(); // Restore state
  }
}

function drawPerfectLineFromCenter(type, p, s) {
  if (p <= 0) return; // Don't draw if progress is zero
  let x1, y1, x2, y2; // End-point variables
  let mid = s / 2; // Tile center point
  switch (type) { // Map index to specific line geometry
    case 1: x1 = 0; y1 = 0; x2 = s; y2 = s; break; // Diagonal TL to BR
    case 2: x1 = s; y1 = 0; x2 = 0; y2 = s; break; // Diagonal TR to BL
    case 3: x1 = mid; y1 = 0; x2 = mid; y2 = s; break; // Center vertical
    case 4: x1 = 0; y1 = mid; x2 = s; y2 = mid; break; // Center horizontal
    case 5: x1 = 0; y1 = 0; x2 = s; y2 = 0; break; // Top edge
    case 6: x1 = 0; y1 = s; x2 = s; y2 = s; break; // Bottom edge
    case 7: x1 = 0; y1 = 0; x2 = 0; y2 = s; break; // Left edge
    case 8: x1 = s; y1 = 0; x2 = s; y2 = s; break; // Right edge
  }
  let curX1 = lerp(mid, x1, p); // Interpolate start X from center
  let curY1 = lerp(mid, y1, p); // Interpolate start Y from center
  let curX2 = lerp(mid, x2, p); // Interpolate end X from center
  let curY2 = lerp(mid, y2, p); // Interpolate end Y from center
  line(curX1, curY1, curX2, curY2); // Draw the animated line segment
}

function mouseReleased() {
  loopStep = (loopStep + 1) % 4; // Manually advance loop phase on click
  initGrid(); // Refresh layout
}

